draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // draw a stick figure with blinders
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 20);
  ctx.lineTo(W/2, H/2 + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 - 20, H/2 + 70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2 + 50);
  ctx.lineTo(W/2 + 20, H/2 + 70);
  ctx.stroke();

  // draw blinders
  ctx.beginPath();
  ctx.rect(W/2 - 30, H/2 - 20, 20, 40);
  ctx.stroke();
  ctx.beginPath();
  ctx.rect(W/2 + 10, H/2 - 20, 20, 40);
  ctx.stroke();

  // draw a truth bubble
  ctx.beginPath();
  ctx.arc(W/2 + 50 + 20*Math.cos(t), H/2 - 50 + 20*Math.sin(t), 10, 0, 2*Math.PI);
  ctx.stroke();

  // draw a believed truth bubble
  ctx.beginPath();
  ctx.arc(W/2 - 50 + 20*Math.cos(t + Math.PI), H/2 - 50 + 20*Math.sin(t + Math.PI), 10, 0, 2*Math.PI);
  ctx.stroke();

  ctx.restore();
}
